// Installed into OpenCode; runs in its Node-compatible plugin runtime.
export const hookSource = String.raw`// yinz-opencode-plugin v6 - generated by yinz hooks install.
// Do not edit; yinz hooks install rewrites this file, and --uninstall
// removes it.
//
// opencode loads this plugin from ~/.config/opencode/plugin/yinz.js. It forwards
// normalized hook events - including interception hooks - to
// whoever owns the pane: yinz action agent-report --hook-json --kind opencode for a
// local pane, yinz --pty-broker report opencode for a remote one. The session reads
// the shared HookEvent contract and carries what the events mean on the
// pane, so the pane reports its own busy/waiting/idle state instead of being guessed at
// from its screen.
//
// Two rules this file keeps, both of which matter:
//   - it never throws. A report that fails must not interfere with the agent it is only
//     reporting on.
//   - callbacks never wait. Reports queue in order, starting after the prior child closes.

import { spawn } from "node:child_process"

const YINZ_BIN = __YINZ_BIN__
const PANE_TOKEN_ENV = __TOKEN_ENV__
const PANE_TOKEN = process.env[PANE_TOKEN_ENV]
const PANE_REF = process.env.YINZ_PANE_REF

let reports = Promise.resolve()

// Agent-specific interpretation stays in the provider; transports only read HookEvent.
function toHookEvent(event) {
  const p = event.properties ?? {}
  const hook = {
    hook_event_name: event.type ?? "",
    session_id: p.sessionID || p.info?.id || "",
    cwd: p.cwd || p.info?.directory,
  }
  const tool = name => ({
    bash: "Bash", read: "Read", write: "Write", edit: "Edit", multiedit: "MultiEdit",
    notebookedit: "NotebookEdit", question: "AskUserQuestion", exitplanmode: "ExitPlanMode",
  })[name?.toLowerCase()] ?? name
  const args = value => value && typeof value === "object" && !Array.isArray(value)
    ? Object.fromEntries(Object.entries(value).map(([key, value]) =>
      [key === "filePath" || key === "filepath" ? "file_path" : key, value]))
    : value
  switch (event.type) {
    case "session.created":
      hook.hook_event_name = "SessionStart"
      hook.source = "startup"
      break
    case "session.deleted": hook.hook_event_name = "SessionEnd"; break
    case "session.idle":
    case "session.error":
      hook.hook_event_name = event.type === "session.idle" ? "Stop" : "StopFailure"
      hook.last_assistant_message = p.lastAssistantMessage
      hook.turn_id = p.turnID
      break
    case "session.compacted": hook.hook_event_name = "PostCompact"; break
    case "chat.message":
      hook.hook_event_name = "UserPromptSubmit"
      hook.prompt = p.prompt
      break
    case "tool.execute.before":
    case "tool.execute.failure":
    case "tool.execute.after":
      hook.hook_event_name = event.type === "tool.execute.before" ? "PreToolUse" : event.type === "tool.execute.failure" ? "PostToolUseFailure" : "PostToolUse"
      hook.tool_name = tool(p.tool)
      hook.tool_use_id = p.callID
      hook.tool_input = args(p.args)
      hook.tool_response = p.output
      hook.error = p.error
      break
    case "permission.asked":
    case "permission.updated": {
      const current = event.type === "permission.asked"
      const name = current ? p.permission : p.type
      const metadata = args(p.metadata)
      const title = current ? p.patterns?.filter(x => typeof x === "string").join(" ") : p.title
      const key = name === "bash" ? "command" : ["read", "edit", "write"].includes(name) ? "file_path" : undefined
      hook.hook_event_name = "PermissionRequest"
      hook.tool_name = tool(name)
      hook.tool_use_id = current ? p.tool?.callID : p.callID
      hook.tool_input = metadata && typeof metadata === "object" && !Array.isArray(metadata)
        && (key ? Object.hasOwn(metadata, key) : Object.keys(metadata).length)
        ? metadata : title ? (key ? { [key]: title } : title) : undefined
      break
    }
    case "permission.replied": hook.hook_event_name = "PostToolUse"; break
    case "assistant.message":
      hook.hook_event_name = "MessageDisplay"
      hook.message_id = p.messageID
      hook.turn_id = p.messageID
      hook.index = 0
      hook.final_batch = true
      hook.delta = p.text
      break
  }
  return hook
}

function report(payload, isParent) {
  // The remote token is tested first, and that order is the whole point: a remote pane
  // carries a token *and* a pane id, and the pane id it carries is the asking session's,
  // on a machine that has no such session. Neither set: not a yinz pane at all, and
  // nothing to report to.
  if (!PANE_TOKEN && !PANE_REF) return
  const args = PANE_TOKEN
    ? ["--pty-broker", "report", "opencode"]
    : ["action", "agent-report", "--hook-json", "--kind", "opencode"]
  let serialized
  try {
    serialized = JSON.parse(JSON.stringify(toHookEvent(payload)))
  } catch {
    return
  }
  reports = reports.then(async () => {
    if (!await isParent(serialized)) return
    serialized = JSON.stringify(serialized)
    return new Promise((resolve) => {
      let child
      try {
        child = spawn(YINZ_BIN, args, { stdio: ["pipe", "ignore", "ignore"] })
      } catch {
        resolve()
        return
      }
      // Node emits close after error, including when spawning fails.
      child.on("error", () => {})
      child.on("close", resolve)
      child.stdin.on("error", () => {})
      try {
        child.stdin.end(serialized)
      } catch {
        child.kill()
      }
    })
  }).catch(() => {})
}

export const Agent = async ({ directory, client }) => {
  // The folder the server is working in. Stamped on every event because an opencode
  // record is complete every time it is set, and an event that omitted the folder
  // would clear one an earlier event had set.
  const cwd = directory
  // Cache whether each session is a parent, including sessions resumed after restart.
  // Classify in report order so metadata lookups cannot reorder pane state changes.
  const sessions = new Map()
  const textParts = new Map()
  const lastAssistant = new Map()

  const send = (type, properties, info) => {
    const sessionID = properties.sessionID
    report({ type, properties: { cwd, ...properties } }, async (hook) => {
      if (!sessionID) return false
      if (info && !sessions.has(sessionID)) sessions.set(sessionID, info.parentID ?? null)
      let root = sessionID
      const visited = new Set()
      while (true) {
        if (visited.has(root)) return false
        visited.add(root)
        if (!sessions.has(root)) {
          const { data, error } = await client.session.get({ path: { id: root } })
          if (error || data?.id !== root) return false
          sessions.set(root, data.parentID ?? null)
        }
        const parent = sessions.get(root)
        if (!parent) break
        root = parent
      }
      if (type === "session.deleted") sessions.delete(sessionID)
      if (root !== sessionID) {
        if (!type.startsWith("tool.execute.")) return false
        hook.session_id = root
        hook.agent_id = sessionID
        hook.archive_only = true
      }
      return true
    })
  }

  const forget = (sessionID) => {
    textParts.delete(sessionID)
    lastAssistant.delete(sessionID)
  }

  return {
    event: async ({ event }) => {
      const p = event.properties ?? {}
      switch (event.type) {
        case "session.created":
        case "session.deleted":
          send(event.type, { sessionID: p.info?.id }, p.info)
          if (event.type === "session.deleted") forget(p.info?.id)
          return
        case "session.idle": {
          const last = lastAssistant.get(p.sessionID)
          send("session.idle", {
            sessionID: p.sessionID,
            lastAssistantMessage: last?.text,
            turnID: last?.messageID,
          })
          return
        }
        case "session.error": {
          const last = lastAssistant.get(p.sessionID)
          send("session.error", {
            sessionID: p.sessionID,
            lastAssistantMessage: last?.text,
            turnID: last?.messageID,
          })
          return
        }
        case "session.compacted":
          send("session.compacted", { sessionID: p.sessionID })
          return
        case "message.part.updated": {
          const part = p.part
          if (part?.type === "tool" && part.state?.status === "error") {
            send("tool.execute.failure", { sessionID: part.sessionID, callID: part.callID,
              tool: part.tool, args: part.state.input, error: part.state.error })
            return
          }
          if (part?.type !== "text" || part.synthetic || part.ignored) return
          const messages = textParts.get(part.sessionID) ?? new Map()
          const parts = messages.get(part.messageID) ?? new Map()
          parts.set(part.id, part.text ?? "")
          messages.set(part.messageID, parts)
          textParts.set(part.sessionID, messages)
          return
        }
        case "message.updated": {
          const info = p.info
          if (info?.role !== "assistant" || !info.time?.completed) return
          const parts = textParts.get(info.sessionID)?.get(info.id)
          const text = parts ? [...parts.values()].join("") : ""
          // Once consumed, the parts are dropped: the message's text lives on in
          // lastAssistant until the next turn replaces it.
          textParts.get(info.sessionID)?.delete(info.id)
          if (!text) return
          lastAssistant.set(info.sessionID, { messageID: info.id, text })
          send("assistant.message", {
            sessionID: info.sessionID,
            messageID: info.id,
            text,
          })
          return
        }
        case "permission.asked":
        case "permission.updated":
          send(event.type, { ...p })
          return
        case "permission.replied":
          send("permission.replied", { sessionID: p.sessionID })
          return
        default:
          return
      }
    },
    "chat.message": async (input, output) => {
      lastAssistant.delete(input.sessionID)
      textParts.delete(input.sessionID)
      const text = (output.parts ?? [])
        .filter((part) => part.type === "text" && !part.synthetic && !part.ignored)
        .map((part) => part.text ?? "")
        .join(" ")
        .trim()
      send("chat.message", {
        sessionID: input.sessionID,
        messageID: output.message?.id,
        prompt: text || undefined,
      })
    },
    "tool.execute.before": async (input, output) => {
      send("tool.execute.before", {
        sessionID: input.sessionID,
        callID: input.callID,
        tool: input.tool,
        args: output.args,
      })
    },
    "tool.execute.after": async (input, output) => {
      send("tool.execute.after", {
        sessionID: input.sessionID,
        callID: input.callID,
        tool: input.tool,
        args: input.args,
        output: output?.output,
      })
    },
  }
}
`;
